    ones=[(i,j) for i in range(H) for j in range(W) if gin[i][j]==1]
    twocomps=comps(gin,2)
    # pairs of 1s sharing row or col
    changed=set()
    for a in range(len(ones)):
        for b in range(a+1,len(ones)):
            (r1,c1),(r2,c2)=ones[a],ones[b]
            if r1==r2:
                lo,hi=min(c1,c2),max(c1,c2)
                ok=all(gin[r1][k] in (0,2) for k in range(lo+1,hi))
                if ok:
