                        for (x,y) in comp:
                            if r1-1<=x<=r1+1 or False: pass
                        # component must overlap the row segment
                        xs=[x for x,_ in comp]; ys=[y for _,y in comp]
                        if min(xs)<=lo and max(xs)>=hi or min(xs)<=hi and max(xs)>=lo and any(lo<=x<=hi for x,_ in comp) and any(lo<=y<=hi for _,y in comp):
                            changed.update(comp)
            elif c1==c2:
                lo,hi=min(r1,r2),max(r1,r2)
                ok=all(gin[k][c1] in (0,2) for k in range(lo+1,hi))
                if ok:
                    for comp in twocomps:
                        xs=[x for x,_ in comp]; ys=[y for _,y in comp]
                        if any(lo<=x<=hi for x,_ in comp) and any(lo<=y<=c1 for _,y in comp):
                            changed.update(comp)
