def comps(g,val):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; res=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]==val and not seen[i][j]:
                st=[(i,j)]; c=[]
                while st:
                    a,b=st.pop()
                    if (a,b) in c: continue
                    c.append((a,b)); seen[a][b]=True
                    for da in(-1,0,1):
                        for db in(-1,0,1):
                            x,y=a+da,b+db
                            if 0<=x<H and 0<=y<W and g[x][y]==val: st.append((x,y))
                res.append(c)
    return res
