def f(gin):
    H,W=len(gin),len(gin[0])
    ones=[(i,j) for i in range(H) for j in range(W) if gin[i][j]==1]
    out=[r[:] for r in gin]
    cor=set()
    # horizontal corridors
    for i in range(H):
        cs=sorted(j for j in range(W) if gin[i][j]==1)
        if len(cs)>=2 and all(gin[i][j]!=1 for j in range(cs[0]+1,cs[-1])):
            for j in range(cs[0],cs[-1]+1): cor.add((i,j))
    # vertical corridors
    for j in range(W):
        rs=sorted(i for i in range(H) if gin[i][j]==1)
        if len(rs)>=2 and all(gin[i][j]!=1 for i in range(rs[0]+1,rs[-1])):
            for i in range(rs[0],rs[-1]+1): cor.add((i,j))
    # blocks strictly intersecting a corridor get fully recolored
    for comp in comps(gin,2):
        if set(comp)&cor:
            for x,y in comp: out[x][y]=1
    # corridor cells become 1
    for c in cor: out[c[0]][c[1]]=1
    return out
